// Some portions generated by Codex
package org.eclipse.rdf4j.query.explanation;

import java.util.List;

import org.eclipse.rdf4j.common.annotation.Experimental;

/** A non-executing snapshot of one physical strategy decision. */
@Experimental
public record StrategyDecision(String decisionPoint, long capturedAtMillis, String mode, String wouldSelect,
		String fallback, String reason, List<Candidate> candidates) {

	/** Transient query-model metadata; never part of an optimizer cache key. */
	public static final Object METADATA_KEY = new Object();

	public StrategyDecision {
		candidates = List.copyOf(candidates);
	}

	/** Null eligibility means the decision requires values produced only during execution. */
	public record Candidate(String strategy, Integer priority, Boolean canAttempt, String decision,
			String declineReason, String condition) {
	}

	public String summary() {
		return "Would select now: "
				+ (wouldSelect != null ? wouldSelect
						: mode.equals("runtime dependent") ? "Runtime dependent"
								: mode.equals("no dispatch") ? "No strategy required" : "No eligible strategy")
				+ " (" + mode + ")" + (fallback == null ? "" : "; fallback: " + fallback);
	}

	public String toText() {
		StringBuilder text = new StringBuilder("Strategies — ").append(decisionPoint)
				.append('\n')
				.append(summary())
				.append('\n')
				.append(reason)
				.append('\n')
				.append("Priority | Strategy | Can attempt? | Decision | Reason\n");
		for (Candidate candidate : candidates) {
			text.append(candidate.priority == null ? "—" : candidate.priority)
					.append(" | ")
					.append(candidate.strategy)
					.append(" | ")
					.append(candidate.canAttempt == null ? "Runtime dependent" : candidate.canAttempt ? "Yes" : "No")
					.append(" | ")
					.append(candidate.decision)
					.append(" | ")
					.append(candidate.declineReason == null ? candidate.condition == null ? "" : candidate.condition
							: candidate.declineReason)
					.append('\n');
		}
		return text.toString();
	}
}
